import {EVENTS,DAYS,DATES,TOPICS,DEFAULT_BLOCKS,time,when} from './data.js';
import {issue,recommend,reasons,parseRequest} from './planner.js';
const paths={compass:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Z M16 8l-3 5-5 3 3-5 5-3Z',home:'m3 10 9-7 9 7v11h-6v-7H9v7H3Z',calendar:'M4 5h16v16H4Z M8 2v6 M16 2v6 M4 11h16 M8 15h2 M14 15h2',search:'M21 21l-5-5 M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Z',chat:'M21 11a9 9 0 0 1-9 9H4l-3 2 1-7a9 9 0 1 1 19-4Z M7 11h.1 M12 11h.1 M17 11h.1',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z M20 2v4 M18 4h4',bookmark:'M6 3h12v18l-6-4-6 4Z',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z M4 21v-2a8 8 0 0 1 16 0v2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4Z M10 21h4',arrow:'M4 12h16 m-6-6 6 6-6 6',plus:'M12 5v14 M5 12h14',check:'m5 12 4 4L19 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Z M12 7v5l3 2',pin:'M12 22s8-8 8-14A8 8 0 0 0 4 8c0 6 8 14 8 14Z M12 5a3 3 0 1 0 0 6 3 3 0 0 0 0-6Z',food:'M5 3v7 M8 3v7 M2 3v7h6 M5 10v11 M18 3c-4 4-4 8 0 9V3v18',send:'m3 3 19 9-19 9 4-9-4-9Z M7 12h15',close:'m6 6 12 12 M6 18 18 6',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',menu:'M3 6h18 M3 12h18 M3 18h18',refresh:'M20 7a9 9 0 1 0 1 8 M20 2v5h-5',users:'M9 3a3 3 0 1 0 0 6 3 3 0 0 0 0-6Z M3 20v-4a6 6 0 0 1 12 0v4 M17 4a3 3 0 0 1 0 6 M18 13a4 4 0 0 1 3 4v3'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.compass}"/></svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='campus-compass-demo-v1';
const fresh=()=>({plan:[],saved:['e1'],blocks:structuredClone(DEFAULT_BLOCKS),interests:['AI & education','Career','Social'],buffer:15,cancelled:[],joined:[],posts:[],draft:[],constraints:{},messages:[],name:'Judy'});
let state=fresh();try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&Array.isArray(s.plan)&&Array.isArray(s.blocks))state={...state,...s};}catch{}
let page=location.hash.slice(1)||'dashboard',filter='All',query='',busy=false;
const labels={dashboard:'Dashboard',calendar:'My Calendar',explore:'Explore Events',forum:'Discussion Forum',planner:'AI Planner',saved:'Saved Events',profile:'Profile',settings:'Settings'};
if(!labels[page])page='dashboard';
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Changes are available for this session only. Browser storage is unavailable.');}}
let timer;function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>t.classList.remove('show'),4200);}
function nav(p){page=p;filter='All';query='';location.hash=p;render();window.scrollTo(0,0);}
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(labels[p]&&p!==page){page=p;render();}});
function button(label,action,id='',cls=''){return `<button class="btn ${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${label}</button>`;}
function footer(){return `<footer class="section-footer"><span>Campus Compass · IBM AI Experiential Learning Lab project</span><span>Fictional data · Demo week, Oct 19–23, 2026 · Eastern Time</span></footer>`;}
function pageHead(title,desc,action=''){return `<div class="page-head"><div><h1>${title}</h1><p class="sub">${desc}</p></div>${action||'<span class="date">Monday, October 19, 2026 · Demo</span>'}</div>`;}
function empty(title,body,action=''){return `<div class="empty">${icon('compass')}<h3>${title}</h3>${body}${action?`<p>${action}</p>`:''}</div>`;}
function card(e){const inPlan=state.plan.includes(e.id),problem=issue(e,state);const type=e.topic==='Arts & culture'?'arts':e.category.toLowerCase();return `<article class="event-card"><div class="poster ${type}"><small>CAMPUS COMPASS / OCTOBER</small><b>${e.poster.replace(' / ','<br>')}</b><button class="icon-btn ${state.saved.includes(e.id)?'selected':''}" data-action="save" data-id="${e.id}" aria-label="${state.saved.includes(e.id)?'Unsave':'Save'} ${esc(e.title)}" aria-pressed="${state.saved.includes(e.id)}">${icon('bookmark')}</button></div><div class="event-body"><span class="tag ${type}">${e.category}</span><button class="event-title" data-action="detail" data-id="${e.id}"><h3>${e.title}</h3></button><div class="meta">${icon('calendar')}${when(e)}</div><div class="meta">${icon('pin')}${e.location}</div><div class="meta">${icon('food')}${e.food==='None'?'No food provided':e.food==='Unknown'?'Food unconfirmed':e.food==='None'?'No food provided':e.food} · ${e.cost?'$'+e.cost:'Free entry'}</div><div class="reason">${problem?esc(problem):`${icon('check')} ${state.interests.includes(e.topic)?'Matches your interests':'Discover something new'} · Fits your schedule`}</div>${button(inPlan?icon('check')+' In your calendar':icon('plus')+' Add to calendar',inPlan?'calendar':'add',e.id,inPlan?'':'')}</div></article>`;}
function week(full=false){return `<div class="week-scroll"><div class="week">${DAYS.map((d,i)=>{const items=[...state.blocks.filter(b=>b.day===i).map(b=>({...b,kind:'class'})),...EVENTS.filter(e=>e.day===i&&state.plan.includes(e.id)).map(e=>({...e,kind:'event'}))].sort((a,b)=>a.start-b.start);return `<div class="week-day"><div class="day-head ${i===0?'today':''}">${d}<strong>${19+i}</strong></div>${items.map(e=>`<${e.kind==='event'?'button':'div'} class="calendar-item ${e.kind} ${state.cancelled.includes(e.id)?'cancelled':''}" ${e.kind==='event'?`data-action="detail" data-id="${e.id}"`:''}><strong>${esc(e.title)}</strong><span>${state.cancelled.includes(e.id)?'Cancelled':`${time(e.start)}${full?' – '+time(e.end):''}`}</span></${e.kind==='event'?'button':'div'}>`).join('')}<button class="add-day" data-action="day" data-id="${i}" aria-label="Find events on ${d}">${icon('plus')} ${full?'Find an event':''}</button></div>`;}).join('')}</div></div>`;}
function filters(){return `<div class="filters">${['All','Academic','Career','Social','Workshops','Free Food'].map(c=>`<button class="chip ${filter===c?'active':''}" data-action="filter" data-id="${c}" aria-pressed="${filter===c}">${c}</button>`).join('')}</div>`;}
function filtered(list){return list.filter(e=>(filter==='All'||(filter==='Free Food'?e.food==='Free meal':e.category===filter))&&(!query||`${e.title} ${e.description} ${e.topic} ${e.food}`.toLowerCase().includes(query.toLowerCase())));}
function dashboard(){let rec=filtered(EVENTS.filter(e=>!state.plan.includes(e.id)&&!issue(e,state))).sort((a,b)=>Number(state.interests.includes(b.topic))-Number(state.interests.includes(a.topic))||a.day-b.day||a.start-b.start);return `${pageHead(`Welcome back, ${esc(state.name)}.`,`A little direction. A world of campus possibilities.`)}<div class="layout"><div class="stack"><section class="hero"><div><h2>Find your people.<br>Make room for possibility.</h2><p>Your next idea, conversation, or favorite campus moment could be just around the corner.</p>${button('Let’s plan your week '+icon('arrow'),'planner')}</div><div class="hero-compass">${icon('compass')}</div></section><section class="panel"><div class="section-bar"><h2>Your week, at a glance</h2><button class="text-btn" data-action="calendar">View calendar ${icon('arrow')}</button></div>${week()}<div class="legend"><span><i class="dot"></i>Classes & personal time</span><span><i class="dot green"></i>Your campus plans</span></div></section><section><div class="section-bar"><h2>A few things you might love</h2><button class="text-btn" data-action="explore">Explore all ${icon('arrow')}</button></div>${filters()}<div class="event-grid">${rec.slice(0,3).map(card).join('')}</div>${!rec.length?empty('Try another category','There are no available matches in this category.'):''}</section></div><aside class="stack rail"><section class="panel planner-teaser"><img class="mascot" src="assets/mascot.png" alt="Campus Compass cat mascot wearing a green compass bandana"><h2>A week that feels like you.</h2><p>Tell me what you’re curious about.<br>I’ll help you find a place to start.</p>${button(icon('spark')+' Meet your AI planner','planner','', 'primary')}<span class="label">SIMULATED CHAT · REAL DEMO INTERACTIONS</span></section><section class="panel"><div class="section-bar"><h2>Around campus</h2>${icon('bell')}</div><div class="feed"><strong>Your weekly possibilities are ready</strong><p>Discover opportunities across learning, career, and community.</p><button class="text-btn" data-action="explore">Take a look ${icon('arrow')}</button></div><div class="feed"><strong>${state.cancelled.length?'An event update needs your attention':'Leave a little breathing room'}</strong><p>${state.cancelled.length?'A fictional cancellation is ready to re-plan.':'Your planner leaves 15 minutes between commitments.'}</p>${state.cancelled.length?'<button class="text-btn" data-action="planner">Review update →</button>':''}</div><div class="feed"><strong>All campus stories here are fictional</strong><p>Explore freely. This is a student-built demonstration.</p></div></section><section class="panel"><div class="section-bar"><h2>Find your community</h2></div>${[['AI & learning circle','Ideas across disciplines'],['Global table','Conversations across cultures'],['Career connections','Your next chapter']].map(([n,d])=>`<div class="group"><span class="group-icon">${icon('users')}</span><div><strong>${n}</strong><small>${d}</small></div></div>`).join('')}<button class="text-btn" data-action="forum">Join the conversation ${icon('arrow')}</button></section></aside></div>${footer()}`;}
function explore(saved=false){const list=filtered(saved?EVENTS.filter(e=>state.saved.includes(e.id)):EVENTS);return `${pageHead(saved?'Your saved possibilities':'Explore campus events',saved?'Keep the things that catch your eye in one place.':'Follow your curiosity. There’s more happening than you think.')}<div class="section-bar">${filters()}<span class="date">${list.length} fictional events</span></div>${query?`<p class="sub" style="margin-bottom:18px">Results for “${esc(query)}” <button class="text-btn" data-action="clear-search">Clear search</button></p>`:''}<div class="event-grid">${list.map(card).join('')}</div>${!list.length?empty(saved?'Your next possibility is out there':'No events found',saved?'Bookmark an event to find it here.':'Try a different keyword or category.',button('Explore events','explore')):''}${footer()}`;}
function draftItem(e){return `<div class="draft-item"><span class="tag">${e.category}</span><button class="event-title" data-action="detail" data-id="${e.id}"><h3>${e.title}</h3></button><div class="meta">${icon('clock')}${when(e)}</div><div class="reason">${reasons(e,state,state.constraints).map(x=>'• '+x).join('<br>')}</div>${button(icon('plus')+' Add to my calendar','add',e.id,'small')}</div>`;}
function planner(){const draft=state.draft.map(id=>EVENTS.find(e=>e.id===id)).filter(e=>e&&!state.plan.includes(e.id)&&!issue(e,state));const messages=state.messages.length?state.messages:[{role:'assistant',text:`Hi ${state.name}! Let’s find a little more of what you love on campus.\n\nTell me your interests, when you’re free, and anything that matters — like free food or a little time between events. I’ll check your demo schedule and suggest a few options.`}];return `${pageHead('Your week, with a little guidance.','Discover opportunities that fit your interests and your actual free time.',button(icon('calendar')+' My calendar','calendar'))}${state.cancelled.some(id=>state.plan.includes(id))?`<div class="notice"><strong>One of your plans has changed.</strong> An event was cancelled in this demonstration. Your other choices will stay in place.<br>${button('Find a replacement','replan','','small')}</div>`:''}<div class="planner-layout"><section class="panel chat-panel"><div class="chat-header"><img src="assets/mascot.png" alt="AI planner mascot"><div><h2>Chat with your campus guide</h2><span class="status-label"><i class="dot green"></i>Demo assistant · Name coming soon</span></div><button class="text-btn" data-action="new-chat" style="margin-left:auto">New chat</button></div><div class="messages" id="messages" aria-live="polite">${messages.map(m=>`<div class="message ${m.role==='user'?'user-msg':''}">${m.role==='assistant'?'<img src="assets/mascot.png" alt="">':''}<div class="bubble">${esc(m.text)}</div></div>`).join('')}${busy?'<div class="message"><div class="bubble">Checking interests, timing, and access…</div></div>':''}</div><div class="prompts">${['AI and education on Tuesday or Thursday afternoons','A social event with free food','Career events after 1 PM'].map(p=>`<button data-action="prompt" data-id="${esc(p)}">${p}</button>`).join('')}</div><form id="chat-form" class="composer"><textarea id="chat-input" aria-label="Message your AI planner" placeholder="I’m interested in AI, but I’m only free Tuesday afternoon…" maxlength="1000" ${busy?'disabled':''}></textarea><button aria-label="Send message" ${busy?'disabled':''}>${icon('send')}</button></form><p class="fineprint">Simulated responses using fictional events. No live AI or external calendar is connected.</p></section><aside class="stack"><section class="panel"><div class="section-bar"><h2>Your draft plan</h2><span class="tag" style="margin:0">${draft.length} ${draft.length===1?'idea':'ideas'}</span></div>${draft.length?draft.map(draftItem).join(''):empty('A little space for possibility','Start a conversation to see a few events selected for you.')}<p class="fineprint">You choose what makes it into your week.</p></section><section class="panel"><div class="section-bar"><h2>What I’m working with</h2>${icon('settings')}</div><div class="summary-line"><span>Demo week</span><strong>Oct 19–23</strong></div><div class="summary-line"><span>Busy commitments</span><strong>${state.blocks.length}</strong></div><div class="summary-line"><span>Travel time</span><strong>${state.buffer} minutes</strong></div><div class="summary-line"><span>Events in your plan</span><strong>${state.plan.filter(id=>!state.cancelled.includes(id)).length}</strong></div><p class="sub" style="font-size:11px;margin-top:14px">${state.interests.map(esc).join(' · ')}</p><button class="text-btn" style="margin-top:12px" data-action="profile">Edit interests & availability ${icon('arrow')}</button></section>${state.plan.some(id=>!state.cancelled.includes(id))?`<section class="panel"><h2>Try a change of plans</h2><p class="sub" style="font-size:11px;margin:12px 0">Simulate a cancellation, then find an alternative that fits.</p>${button('Simulate event cancellation','cancel-demo','','small')}</section>`:''}</aside></div>${footer()}`;}
function calendar(){return `${pageHead('Make room for what matters.','Your classes, your plans, and a little breathing room.',button(icon('download')+' Export calendar','export'))}${state.cancelled.some(id=>state.plan.includes(id))?'<div class="notice">A planned event was cancelled. <button class="text-btn" data-action="replan">Find a replacement →</button></div>':''}<section class="panel calendar-full"><div class="section-bar"><h2>October 19–23, 2026</h2><button class="text-btn" data-action="profile">Edit availability ${icon('arrow')}</button></div>${week(true)}<div class="legend"><span><i class="dot"></i>Busy commitments</span><span><i class="dot green"></i>Chosen events</span><span>Eastern Time · ${state.buffer}-minute travel buffer</span></div></section><section style="margin-top:28px"><div class="section-bar"><h2>Your campus plans</h2><button class="text-btn" data-action="planner">Find my next event ${icon('arrow')}</button></div>${state.plan.length?state.plan.map(id=>{const e=EVENTS.find(e=>e.id===id);return `<div class="block-row"><div><strong>${e.title}${state.cancelled.includes(id)?' · Cancelled':''}</strong><small>${when(e)} · ${e.location}</small></div>${button('Remove','remove',id,'small')}</div>`;}).join(''):empty('Your week is waiting','Choose an event or ask the planner to help you get started.',button('Plan with me','planner','','primary'))}</section>${footer()}`;}
function profile(){return `${pageHead('A little about you.','Your interests and availability help make better recommendations.')}<div class="wide-grid"><section class="panel"><h2>What are you curious about?</h2><p class="sub" style="margin-top:10px">Explore beyond your major. These can change anytime.</p><form id="profile-form"><div class="topic-options">${TOPICS.map(t=>`<label><input type="checkbox" name="topics" value="${t}" ${state.interests.includes(t)?'checked':''}>${t}</label>`).join('')}</div><label class="field">Demo display name<input name="name" value="${esc(state.name)}" maxlength="30" required></label><p class="sub" style="font-size:10px;margin:12px 0">Use a fictional profile for classroom demonstrations. Changes stay in this browser.</p><button class="btn primary">Save preferences</button></form></section><section class="panel"><h2>Your busy times</h2><p class="sub" style="margin-top:10px">Sample classes and personal commitments.</p>${state.blocks.map(b=>`<div class="block-row"><div><strong>${esc(b.title)}</strong><small>${DAYS[b.day]} · ${time(b.start)}–${time(b.end)}</small></div><button class="icon-btn" data-action="remove-block" data-id="${b.id}" aria-label="Remove ${esc(b.title)}">${icon('close')}</button></div>`).join('')}</section><section class="panel"><h2>Block off some time</h2><form id="block-form" class="form-grid" style="margin-top:20px"><label class="field full">Commitment<input name="title" required maxlength="60" placeholder="Study group"></label><label class="field full">Day<select name="day">${DAYS.map((d,i)=>`<option value="${i}">${d}, Oct ${19+i}</option>`).join('')}</select></label><label class="field">From<input name="start" type="time" required value="14:00"></label><label class="field">Until<input name="end" type="time" required value="15:00"></label><div class="field full"><button class="btn primary">Add busy time</button><span id="block-error" role="alert"></span></div></form></section><section class="panel"><h2>Calendar connections</h2><div class="settings-row"><div><h3>Google Calendar</h3><p>Sample availability is loaded for this demo.</p></div><span class="tag">Not connected</span></div><div class="settings-row"><div><h3>Canvas</h3><p>Classes are fictional and editable.</p></div><span class="tag">Not connected</span></div><p class="sub" style="font-size:11px">You can export chosen events as an .ics file without connecting an account.</p></section></div>${footer()}`;}
const seedPosts=[{name:'Alex',title:'Anyone exploring AI and education this week?',body:'I’m planning to try the learning lab. Would love to meet students from other programs.',tag:'AI & learning circle'},{name:'Sam',title:'A shared table for new connections',body:'The community dinner looks like a nice way to meet people beyond our own classes.',tag:'Global table'},{name:'Taylor',title:'Making a little room for creativity',body:'Who else is interested in the sketchbook walk? No drawing experience needed.',tag:'Arts & culture'}];
function forum(){return `${pageHead('Good things start with a hello.','A sample community board for the Campus Compass demonstration.')}<div class="wide-grid"><section class="panel"><h2>Campus conversations</h2>${[...state.posts,...seedPosts].map((p,i)=>`<article class="discussion"><div class="avatar">${esc(p.name[0])}</div><div><h3>${esc(p.title)}</h3><small>${esc(p.name)} · Fictional demo participant · ${esc(p.tag)}</small><p>${esc(p.body)}</p><button class="text-btn" data-action="join" data-id="${esc(p.title)}">${state.joined.includes(p.title)?icon('check')+' Joined locally':icon('plus')+' Join conversation'}</button></div></article>`).join('')}</section><section class="panel" style="align-self:start"><h2>Start a conversation</h2><p class="sub" style="font-size:11px;margin:10px 0 20px">Demo posts stay on this device and are not shared with anyone.</p><form id="post-form" class="form-grid"><label class="field full">Topic<input name="title" required maxlength="100" placeholder="What are you curious about?"></label><label class="field full">Message<textarea name="body" required maxlength="600" placeholder="Say hello to the demo community…"></textarea></label><div class="field full"><button class="btn primary">Post to local demo</button></div></form></section></div>${footer()}`;}
function settings(){return `${pageHead('Keep things your way.','A few useful settings for your demonstration.')}<section class="panel"><div class="settings-row"><div><h3>Leave time to get there</h3><p>Keep a 15-minute buffer between events and busy commitments.</p></div><input type="checkbox" id="buffer-toggle" aria-label="15-minute travel buffer" ${state.buffer?'checked':''}></div><div class="settings-row"><div><h3>AI connection</h3><p>Simulated planner. IBM watsonx integration is planned for a later step.</p></div><span class="tag">Demo mode</span></div><div class="settings-row"><div><h3>Start the demonstration again</h3><p>Clear locally saved plans, messages, posts, and preferences.</p></div>${button('Reset demo','reset','','danger')}</div></section><section class="panel" style="margin-top:24px"><h2>About Campus Compass</h2><p class="sub" style="margin-top:12px;max-width:70ch">A higher-education opportunity discovery project for the IBM AI Experiential Learning Lab. Built to help students turn scattered possibilities into a feasible weekly plan.</p><p class="sub" style="margin-top:12px">Team: Judy, Shuozishan Wang, Chenxi Liu, and Tingting Lai.</p><p class="sub" style="margin-top:12px;font-size:11px">All events, student stories, and schedules in this demonstration are fictional. This is a student project, not an official university or IBM product. IBM Bob development work and live watsonx integration must be completed and documented separately.</p></section>${footer()}`;}
function render(){const navs=[['dashboard','home'],['calendar','calendar'],['explore','search'],['forum','chat'],['planner','spark'],['saved','bookmark'],['profile','user'],['settings','settings']];document.querySelector('#app').innerHTML=`<aside class="sidebar" id="sidebar"><a class="brand" href="#dashboard"><span class="logo">${icon('compass')}</span><span>Campus<small>COMPASS</small></span></a><nav class="nav" aria-label="Main navigation">${navs.map(([p,i],n)=>`${n===6?'<div class="break"></div>':''}<button data-action="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}${labels[p]}${p==='saved'&&state.saved.length?`<span class="badge">${state.saved.length}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="demo-note"><strong>A campus of possibilities.</strong>Your interests. Your time. Your next great discovery.</div><div class="user"><span class="avatar">${esc(state.name[0]||'J')}</span><div><strong>${esc(state.name)}’s campus</strong><small>Graduate student · Demo profile</small></div></div></div></aside><div class="shell"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Toggle navigation" aria-expanded="false" aria-controls="sidebar">${icon('menu')}</button><div class="breadcrumb">My campus <span>/ &nbsp; ${labels[page]}</span></div><form id="search-form" class="search">${icon('search')}<input name="q" aria-label="Search events" placeholder="Find something that sparks your interest" value="${esc(query)}"></form><div class="top-actions"><span class="term">Fall semester 2026</span><button class="icon-btn" data-action="notifications" aria-label="View notifications">${icon('bell')}</button><button class="avatar" data-action="profile" aria-label="Open profile" style="border:0">${esc(state.name[0]||'J')}</button></div></header><main class="page-enter" id="main">${({dashboard,calendar,explore,planner,saved:()=>explore(true),profile,forum,settings}[page])()}</main></div>`;bind();const msgs=document.querySelector('#messages');if(msgs)msgs.scrollTop=msgs.scrollHeight;}
function detail(id){const e=EVENTS.find(e=>e.id===id);if(!e)return;const problem=issue(e,state),inPlan=state.plan.includes(id),d=document.querySelector('#detail');d.innerHTML=`<button class="icon-btn close" data-action="close" aria-label="Close details">${icon('close')}</button><span class="tag">${e.category} · Fictional event</span><h2>${e.title}</h2><p>${e.description}</p><div class="meta">${icon('calendar')}${when(e)} · Eastern Time</div><div class="meta">${icon('pin')}${e.location}</div><div class="meta">${icon('food')}${e.food==='Unknown'?'Food availability unknown':e.food} · ${e.cost?'$'+e.cost:'Free admission'}</div><div class="meta">${icon('users')}${e.access==='open'?'Open to all demo students':e.access==='members'?'Membership required':e.access==='full'?'At capacity':'Eligibility not confirmed'} · ${e.rsvp}</div>${problem?`<div class="notice">${esc(problem)}</div>`:`<p class="reason">${reasons(e,state).join('<br>')}</p>`}<div class="source"><strong>Record & evidence</strong><br>${e.source}<br>Authored for this prototype · Last reviewed ${e.checked}<br>No real organizer, source page, RSVP, or attendance claim. Adding an event does not reserve a place.</div><div class="row">${button(inPlan?'Remove from calendar':icon('plus')+' Add to calendar',inPlan?'remove':'add',id,'primary')}${button(state.saved.includes(id)?'Unsave event':'Save event','save',id)}</div>`;if(!d.open)d.showModal();}
function add(id){const e=EVENTS.find(e=>e.id===id);if(!e)return;if(state.plan.includes(id)){toast('This event is already in your calendar.');return;}const problem=issue(e,state);if(problem){toast(problem);detail(id);return;}state.plan.push(id);state.draft=state.draft.filter(x=>x!==id);persist();document.querySelector('#detail').close();render();toast('Added to your calendar. RSVP is not submitted.');}
async function chat(text){if(busy||!text.trim())return;text=text.trim();state.messages.push({role:'user',text});busy=true;render();await new Promise(r=>setTimeout(r,450));const parsed=parseRequest(text,state.constraints);state.constraints=parsed;let response;
 if(/\b(cancelled|canceled|replacement|replan|re-plan)\b/i.test(text)&&state.cancelled.some(id=>state.plan.includes(id))){replan(false);busy=false;persist();render();return;}
 const recognizable=/\b(ai|education|research|learning|tech|coding|data|career|job|industry|alumni|networking|resume|social|friend|friends|meet|people|dinner|lunch|community|art|arts|culture|cultural|film|museum|creative|sketch|wellbeing|wellness|relax|mindful|movement|quiet|plan|event|events|week|free|after|before|afternoon|morning|evening|tuesday|thursday|monday|wednesday|friday|weekend|coffee|tea|options|choices|reset|start over)\b/i.test(text);
 if(!recognizable){response='I’m a limited demo planner. Try an interest such as AI, career, social, arts, or wellbeing, plus a day or time. For example: “AI events on Tuesday after 1 PM.” I can also filter for free meals.';}
 else {const matches=recommend(state,parsed);state.draft=matches.map(e=>e.id);if(matches.length){response=`I found ${matches.length} ${matches.length===1?'option':'options'} for your week. Each fits your current commitments${state.buffer?' with a 15-minute travel buffer':''}.\n\n${matches.map(e=>`${e.title}\n${when(e)} · ${e.food==='Unknown'?'Food unconfirmed':e.food==='None'?'No food provided':e.food}`).join('\n\n')}\n\nThey’re in your draft plan. Add the ones you like, or tell me what to change.`;}else{response='I couldn’t find a verified, conflict-free match for those constraints in this demo week. I haven’t changed your calendar.\n\nTry a different day or interest, or say “start over” to clear time and food filters. Only Monday–Friday events are available. Restricted, full, cancelled, and conflicting events are excluded.';}}
 state.messages.push({role:'assistant',text:response});busy=false;persist();render();document.querySelector('#chat-input')?.focus();}
function replan(go=true){const cancelled=state.plan.filter(id=>state.cancelled.includes(id));if(!cancelled.length){toast('There are no cancelled events in your plan.');return;}const old=EVENTS.find(e=>e.id===cancelled[0]);state.plan=state.plan.filter(id=>id!==old.id);let matches=recommend(state,{...state.constraints,topics:[old.topic]},1);let trade='';if(!matches.length){const relaxed={...state.constraints,topics:[old.topic]};delete relaxed.days;delete relaxed.after;delete relaxed.before;matches=recommend(state,relaxed,1);trade='I relaxed your chat day/time filters to show a possible alternative; review the new time before adding it.';}state.draft=matches.map(e=>e.id);state.messages.push({role:'assistant',text:`“${old.title}” was cancelled in this simulation. I removed the cancelled entry and kept all your other calendar choices.\n\n${matches.length?`An alternative is “${matches[0].title}” on ${when(matches[0])}. It shares the ${old.topic.toLowerCase()} topic and fits your schedule. ${trade}\n\nIt’s a suggestion only. Add it if it works for you.`:'No eligible alternative in the same topic fits your current schedule. Try changing your availability or choosing another interest.'}`});persist();if(go)nav('planner');}
function exportCalendar(){const chosen=EVENTS.filter(e=>state.plan.includes(e.id)&&!state.cancelled.includes(e.id));if(!chosen.length){toast('Add an event to your calendar before exporting.');return;}const stamp=(e,m)=>{const date=new Date(`${DATES[e.day]}T00:00:00-04:00`);date.setUTCMinutes(date.getUTCMinutes()+m);return date.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');};const clean=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Campus Compass//Fictional Demo//EN','CALSCALE:GREGORIAN',...chosen.flatMap(e=>['BEGIN:VEVENT',`UID:${e.id}-20261019@campus-compass-demo`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART:${stamp(e,e.start)}`,`DTEND:${stamp(e,e.end)}`,`SUMMARY:${clean('[DEMO] '+e.title)}`,`LOCATION:${clean(e.location)}`,'DESCRIPTION:Fictional Campus Compass demonstration event. No real reservation.','END:VEVENT']),'END:VCALENDAR'];const blob=new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='campus-compass-demo-week.ics';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Exported chosen events. Cancelled events were excluded.');}
function act(action,id){if(labels[action]){document.querySelector('#detail').close();nav(action);return;}if(action==='save'){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();if(document.querySelector('#detail').open)detail(id);return;}if(action==='detail')return detail(id);if(action==='close')return document.querySelector('#detail').close();if(action==='add')return add(id);if(action==='remove'){state.plan=state.plan.filter(x=>x!==id);persist();document.querySelector('#detail').close();render();toast('Removed from your calendar.');}if(action==='filter'){filter=id;render();}if(action==='clear-search'){query='';render();}if(action==='day'){state.constraints={days:[+id]};nav('planner');chat(`Find events on ${['Monday','Tuesday','Wednesday','Thursday','Friday'][+id]}`);}if(action==='prompt'){state.constraints={};chat(id);}if(action==='new-chat'){state.messages=[];state.constraints={};state.draft=[];persist();render();}if(action==='remove-block'){state.blocks=state.blocks.filter(b=>b.id!==id);persist();render();}if(action==='join'){state.joined=state.joined.includes(id)?state.joined.filter(x=>x!==id):[...state.joined,id];persist();render();toast('Updated locally. No message was sent.');}if(action==='menu'){const open=document.querySelector('#sidebar').classList.toggle('open');document.querySelector('.mobile-menu').setAttribute('aria-expanded',String(open));}if(action==='export')exportCalendar();if(action==='notifications'){nav('dashboard');toast(state.cancelled.length?'An event was cancelled in the demo. Open AI Planner to review.':'Your weekly event suggestions are ready. All updates are fictional.');}if(action==='cancel-demo'){const id=state.plan.find(id=>!state.cancelled.includes(id));if(!id)return;state.cancelled.push(id);persist();render();toast('Demo cancellation created. Your other events are unchanged.');}if(action==='replan')replan();if(action==='reset'){const d=document.querySelector('#detail');d.innerHTML=`<h2>Reset your demo?</h2><p>This clears plans, saved events, chats, and local posts, then restores the sample profile.</p><div class="row">${button('Keep my changes','close')}${button('Reset demo','confirm-reset','','primary')}</div>`;d.showModal();}if(action==='confirm-reset'){state=fresh();persist();document.querySelector('#detail').close();nav('dashboard');toast('Demo restored. You’re ready to present.');}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)act(b.dataset.action,b.dataset.id);});
function bind(){document.querySelector('#search-form')?.addEventListener('submit',e=>{e.preventDefault();query=new FormData(e.target).get('q').trim();page='explore';location.hash='explore';filter='All';render();});document.querySelector('#chat-form')?.addEventListener('submit',e=>{e.preventDefault();chat(document.querySelector('#chat-input').value);});document.querySelector('#chat-input')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();chat(e.target.value);}});document.querySelector('#profile-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);state.name=f.get('name').trim()||'Judy';state.interests=f.getAll('topics');persist();render();toast('Preferences saved. Ask the planner for updated suggestions.');});document.querySelector('#block-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),mins=s=>s.split(':').reduce((a,v,i)=>a+(+v)*(i?1:60),0);const b={id:'b'+Date.now(),title:f.get('title').trim(),day:+f.get('day'),start:mins(f.get('start')),end:mins(f.get('end'))};if(!b.title||b.end<=b.start){document.querySelector('#block-error').textContent='Enter a title and an end time later than the start time.';return;}const conflicts=EVENTS.filter(e=>state.plan.includes(e.id)&&e.day===b.day&&e.start<b.end+state.buffer&&b.start<e.end+state.buffer);if(conflicts.length){document.querySelector('#block-error').textContent=`This overlaps ${conflicts[0].title}. Remove that event from your calendar first.`;return;}state.blocks.push(b);persist();render();toast('Busy time added. Future recommendations will respect it.');});document.querySelector('#post-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim(),body=f.get('body').trim();if(!title||!body)return;state.posts.unshift({name:state.name,title,body,tag:'Local demo post'});persist();render();toast('Posted to your local demo only.');});document.querySelector('#buffer-toggle')?.addEventListener('change',e=>{const previous=state.buffer;state.buffer=e.target.checked?15:0;const conflicts=EVENTS.filter(x=>state.plan.includes(x.id)&&!state.cancelled.includes(x.id)).find(x=>issue(x,state));if(conflicts){state.buffer=previous;render();toast(`Remove ${conflicts.title} before enabling a longer travel buffer.`);return;}persist();toast('Travel buffer updated.');});}
render();

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('#sidebar')?.classList.contains('open')){document.querySelector('#sidebar').classList.remove('open');const toggle=document.querySelector('.mobile-menu');toggle?.setAttribute('aria-expanded','false');toggle?.focus();}});
